INSERT INTO public.projects (id,title_ru,title_en,description_ru,description_en,year,kind,interior_enabled,source,cover_artwork_id,sort_order,updated_at) VALUES ('tavrida','Эскиз для проекта «Таврида»','Sketch for the Tavrida project','Эскиз для проекта «Таврида» был разработан Просецкой Юлией, в дальнейшем воспроизведён на 100 кв. м за 1 час. В выполнении работы приняли участие 300 человек. Данная картина была занесена в Книгу рекордов России.','The sketch for the Tavrida project was designed by Yulia Prosetskaya and subsequently reproduced over 100 square metres in one hour. Three hundred people took part. The painting was entered in the Russian Book of Records.','','painting',true,'https://prosetskaya.ru/razrabotka-eskiza-dlya-proekta-tavrida',NULL,2,'2026-11-15T05:53:33.636546+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.projects (id,title_ru,title_en,description_ru,description_en,year,kind,interior_enabled,source,cover_artwork_id,sort_order,updated_at) VALUES ('individual','Индивидуальные проекты','Individual projects','«Очаровательный животик».\n\nЕсли вы желаете заказать авторскую картину, оставьте заявку для обсуждения деталей. Заказы отправляются по всей территории России и за границу при помощи транспортных компаний.','“Charming tummy”.\n\nTo commission an original painting, get in touch to discuss the details. Works can be shipped throughout Russia and internationally by transport companies.','','painting',true,'https://prosetskaya.ru/individualnye-proekty',NULL,3,'2026-11-15T05:53:33.636546+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.projects (id,title_ru,title_en,description_ru,description_en,year,kind,interior_enabled,source,cover_artwork_id,sort_order,updated_at) VALUES ('other-projects','Другие спецпроекты','Other special projects','Юлия Просецкая как художница известна не только в России, но и за её пределами. Работает с корпоративными клиентами, которые заказывают картины для интерьера ресторанов, гостиниц, спортивных комплексов. Занимается росписью стен: в числе известных проектов — работа специально для сериала о Борисе Годунове.','Yulia Prosetskaya is known as an artist in Russia and abroad. She works with corporate clients on paintings for restaurant, hotel and sports-complex interiors. Her murals include work for a series about Boris Godunov.','','photo',false,'https://prosetskaya.ru/proekty',NULL,4,'2026-11-15T05:53:33.636546+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.projects (id,title_ru,title_en,description_ru,description_en,year,kind,interior_enabled,source,cover_artwork_id,sort_order,updated_at) VALUES ('illustration-projects','Иллюстрации · спецпроекты','Illustration projects','Авторская иллюстрация из раздела спецпроектов.','An original illustration from the special-project catalogue.','','painting',true,'https://prosetskaya.ru/illyustracii',NULL,5,'2026-11-15T05:53:33.636546+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.projects (id,title_ru,title_en,description_ru,description_en,year,kind,interior_enabled,source,cover_artwork_id,sort_order,updated_at) VALUES ('logos','Разработка логотипов','Logo design','Авторская разработка логотипов и фирменных знаков.','Original logo and brand mark design.','','painting',false,'https://prosetskaya.ru/razrabotka-logotipov',NULL,6,'2026-11-17T01:06:37.566923+00:00') ON CONFLICT DO NOTHING;
