INSERT INTO public.projects (id,title_ru,title_en,description_ru,description_en,year,kind,interior_enabled,source,cover_artwork_id,sort_order,updated_at) VALUES ('godunov','Сериал «Годунов»','TV series “Godunov”','Работа художника-декоратора для исторического сериала «Годунов»: исторические росписи, художественные декорации и живописный реквизит для съёмочной площадки и павильонов.','Set-decoration work for the historical TV series “Godunov”: historical murals, painted sets and props for the film set and studio pavilions.','','photo',false,'godunov','godunov-1',-1,'2026-11-21T18:54:34.195216+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.projects (id,title_ru,title_en,description_ru,description_en,year,kind,interior_enabled,source,cover_artwork_id,sort_order,updated_at) VALUES ('murals','Роспись','Murals','Художественная роспись стен и потолков в частных интерьерах, детских комнатах и общественных пространствах.','Hand-painted walls and ceilings for private interiors, nurseries and public spaces.','','photo',false,'','mural-wall-9',1,'2026-11-21T19:31:47.168312+00:00') ON CONFLICT DO NOTHING;
